CREATE FUNCTION public.validate_study_item() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p jsonb:=NEW.payload; BEGIN IF NEW.kind IN ('questions','mock') THEN IF (p->>'total')::integer<=0 OR (p->>'correct')::integer<0 OR (p->>'wrong')::integer<0 OR (p->>'blank')::integer<0 OR (p->>'correct')::integer+(p->>'wrong')::integer+(p->>'blank')::integer<>(p->>'total')::integer THEN RAISE EXCEPTION 'Acertos + erros + brancos devem ser iguais ao total'; END IF; IF p->>'date' IS NULL OR p->>'contest_id' IS NULL THEN RAISE EXCEPTION 'Data e concurso obrigatórios'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_study_item BEFORE INSERT OR UPDATE ON public.study_items FOR EACH ROW EXECUTE FUNCTION public.validate_study_item();
CREATE FUNCTION public.restore_studies(items jsonb, sessions jsonb DEFAULT '[]') RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE x jsonb; n integer:=0; k integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF; IF jsonb_typeof(items)<>'array' OR jsonb_typeof(sessions)<>'array' THEN RAISE EXCEPTION 'Backup inválido'; END IF; FOR x IN SELECT value FROM jsonb_array_elements(items) LOOP INSERT INTO study_items(id,user_id,kind,payload,created_at) VALUES((x->>'id')::uuid,auth.uid(),x->>'kind',x->'payload',coalesce((x->>'created_at')::timestamptz,now())) ON CONFLICT(id) DO NOTHING; GET DIAGNOSTICS k=ROW_COUNT; n:=n+k; END LOOP; FOR x IN SELECT value FROM jsonb_array_elements(sessions) LOOP IF x->>'state'<>'finished' THEN RAISE EXCEPTION 'Sessões ativas não podem ser restauradas'; END IF; INSERT INTO study_sessions(id,user_id,contest_ids,subject_id,topic_id,state,started_at,running_since,elapsed_seconds,finished_at,pauses,notes) VALUES((x->>'id')::uuid,auth.uid(),ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(x->'contest_ids')),(x->>'subject_id')::uuid,(x->>'topic_id')::uuid,'finished',(x->>'started_at')::timestamptz,NULL,(x->>'elapsed_seconds')::numeric,(x->>'finished_at')::timestamptz,coalesce(x->'pauses','[]'),coalesce(x->>'notes','')) ON CONFLICT(id) DO NOTHING; GET DIAGNOSTICS k=ROW_COUNT; n:=n+k; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.restore_studies(jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.restore_studies(jsonb,jsonb) TO authenticated;